/// <summary>
///     The <c>AVADirNameAffix_DirNameAffixTranslateButtonBtn_Extension</c> class is the execution FormControl for <c>DirNameAffix</c>
/// </summary>
[ExtensionOf(FormControlStr(DirNameAffix, DirNameAffixTranslateButton)) ]
final class AVADirNameAffix_DirNameAffixTranslateButtonBtn_Extension
{
}

Method.Source:
/// <summary>
///    AVA <c>Clicked</c> class.
/// </summary>
public void Clicked()
{
    FormRun         formRun;
    FormDataSource  DirNameAffixDS;
    DirNameAffix    locDirNameAffix;

    SysTranslationHelper    sysTranslationHelper;

    formRun         = this.formRun();
    DirNameAffixDS  = formRun.dataSource('DirNameAffix');
    locDirNameAffix = element.DirNameAffix;

    sysTranslationHelper    = new SysTranslationHelper( tableNum(DirNameAffix),
                                                        tableNum(AVADirNameAffixTranslation)
                                                        );
    /*
    // this is to show DirNameAffix.TitleId, which is not a/part of NaturalKey, in the SysTranslation grid form.
    // due to no unique index on EcoResAttribute table below line is required.
    // Please note that “setMainTableNaturalKeyFieldId” is a misnomer – it basically allows any (one) given field to be specified to appear in TranslationList form instead of the NaturalKey field
    */
    sysTranslationHelper.setMainTableNaturalKeyFieldId(fieldNum(DirNameAffix, Affix));

    sysTranslationHelper.launchTranslationDetailForm(locDirNameAffix.RecId);

    next Clicked();

    DirNameAffixDS.research(true);
}
